/** Entrada: W77-FUN-PROY y WKS-SISTEMA, que el WFL pasa al CALL. */
public record ProyFechaRequest(FuncionProyeccion funcion, int sistema) {

    JobParameters toJobParameters() {
        return new JobParametersBuilder()
                .addString("funcion", funcion.name())
                .addLong("sistema", (long) sistema)
                .toJobParameters();
    }
}

