// Se publica en el ExecutionContext del job; el Flow llamador lo lee al terminar el step.

public enum FuncionProyeccion {
    PROYECTA_Y_GRABA(0), GENERA_ARCHIVOS(1), PROYECTA_SIN_GRABAR(2),
    PROYECTA_CONSULTA(3), BORRA_L002_22(4), BORRA_L002_23(5), CONSULTA(6);
    final int codigo;
    FuncionProyeccion(int c) { codigo = c; }
    static FuncionProyeccion of(int c) {
        return Arrays.stream(values()).filter(f -> f.codigo == c).findFirst()
                .orElseThrow(() -> new ProcesoAbortadoException("NUMERO DE FUNCION INVALIDA"));
    }
}

@Component
@RequiredArgsConstructor
public class FuncionProyeccionDecider implements JobExecutionDecider {

    private final ProyFechaProperties props;   // sistema-global: 999

    @Override
    public FlowExecutionStatus decide(JobExecution job, StepExecution step) {
        var f = FuncionProyeccion.valueOf(job.getJobParameters().getString("funcion"));
        long sistema = job.getJobParameters().getLong("sistema");
        if (sistema == props.sistemaGlobal() && f != FuncionProyeccion.PROYECTA_SIN_GRABAR) {
            return new FlowExecutionStatus("FUNCION_INVALIDA");   // solo se registra, no aborta
        }
        return new FlowExecutionStatus(f.name());
    }
}
// En el Job: .on("PROYECTA_Y_GRABA").to(verificaB05).on("PENDIENTE").to(proyectaFecha) ...

@Component
@RequiredArgsConstructor
public class AltaDisponibilidadGuard implements JobExecutionDecider {

    private final ControlProcesosClient b05;   // B05PROCESOS IN LIB-CONTROL

    /** 01-0040-VERIFICA-B05: si el proceso ya terminó para esa fecha, no se reproyecta. */
    @Override
    public FlowExecutionStatus decide(JobExecution job, StepExecution step) {
        var clave = new ClaveProceso(sistema(job), fechaProcesoB05(job), 1);   // NUMPRO = 1
        var registro = b05.consulta(clave)                                    // función 1
                .orElseGet(() -> b05.alta(clave));                            // no existe: función 19 con STAPGM 0
        return registro.terminado()                                           // STAPGM = 1
                ? new FlowExecutionStatus("YA_PROCESADO")
                : new FlowExecutionStatus("PENDIENTE");
    }
}

@Configuration
public class ProyeccionFechaFlow {

    @Bean
    Flow proyectaFecha(Step abreBaseSemanal, Step validaSistema, Step calculaFechas,
                       Step proyectaNiveles, Step grabaFechas, Step avisaL002,
                       Step proyectaTodosLosSistemas, SistemaDecider porSistema) {
        return new FlowBuilder<SimpleFlow>("proyectaFecha")
                .start(porSistema)                                // WKS-SISTEMA = 0 o un sistema
                .on("TODOS").to(proyectaTodosLosSistemas)         // 01-0117 / 01-0118 con B04SISTEM
                .from(porSistema).on("UNO")
                    .to(abreBaseSemanal)                          // 01-0116-ABRE-BASE
                    .next(validaSistema)                          // 01-0120
                    .next(calculaFechas)                          // 01-0130-PROYECTA-FECHA
                    .next(proyectaNiveles)                        // 01-0131-PROYFECHA
                    .next(grabaFechas)                            // 01-0140, solo graba con función 0
                    .next(avisaL002)                              // L002 función 22 (fn 2) o 25 (fn 0)
                .end();
    }
}

