@Bean
RetryTemplate aperturaBaseSemanal(ProyFechaProperties p) {
    return RetryTemplate.builder()
            .maxAttempts(p.baseSemanal().maxIntentos())
            .fixedBackoff(p.baseSemanal().esperaReintento().toMillis())   // WAIT(20)
            .retryOn(BaseEnUsoExclusivoException.class)                    // OPENERROR, tipo 39
            .build();
}

@Bean
Step abreBaseSemanal(JobRepository repo, PlatformTransactionManager tx,
                     RetryTemplate aperturaBaseSemanal, BaseSemanalRepository base) {
    return new StepBuilder("abreBaseSemanal", repo)
            .tasklet((contrib, ctx) -> {
                aperturaBaseSemanal.execute(r -> base.abreParaActualizar(),
                        r -> { throw new ProcesoAbortadoException(
                                "ERROR EN BASE BD10 : ARCHIVO DE CONTROL EN USO EN FORMA EXCLUSIVA"); });
                return RepeatStatus.FINISHED;
            }, tx).build();
}

/** 01-0120-VALIDA-SISTEMA: STAREG = 1 indica que ya se proyectó y no se ha cerrado el día. */
void validaEstatus(ControlSistemaDia ctl, FuncionProyeccion f) {
    if (ctl.sistema() > 0
            && ctl.estatusRegistro() == 1                     // WKS-B01-STAREG
            && f == FuncionProyeccion.PROYECTA_Y_GRABA) {
        throw new ProcesoAbortadoException(
                "ESTATUS INVALIDO PARA PROYECCION DE FECHA S" + ctl.sistema());
    }
}

/** Reemplaza THECALENDAR IN LOCSUP con un calendario bancario explícito. */
@Service
@RequiredArgsConstructor
public class CalendarioBancario {

    private final DiasInhabilesRepository inhabiles;   // catálogo que hoy vive en LOCSUP

    public FechasProyectadas proyecta(LocalDate actual) {
        LocalDate manana   = sumaHabiles(actual, 1);    // función 13, formato 13
        LocalDate pasado   = sumaHabiles(manana, 1);
        LocalDate tercero  = sumaHabiles(pasado, 1);   // WKS-FECHA-3ERHABIL
        LocalDate natural  = actual.plusDays(1);        // función 8: día natural
        LocalDate ayer     = restaUno(actual);          // función 15: semántica por confirmar
        return new FechasProyectadas(manana, pasado, tercero, natural, ayer);
    }

    LocalDate sumaHabiles(LocalDate f, int n) {
        LocalDate d = f;
        for (int i = 0; i < n; ) {
            d = d.plusDays(1);
            if (esHabil(d)) i++;
        }
        return d;
    }

    boolean esHabil(LocalDate d) {
        return d.getDayOfWeek() != DayOfWeek.SATURDAY
                && d.getDayOfWeek() != DayOfWeek.SUNDAY
                && !inhabiles.existsByFecha(d);
    }

    LocalDate restaUno(LocalDate f) {
        return f.minusDays(1);   // ajustar a hábil si el SME confirma que la función 15 es hábil
    }
}

@Service
@RequiredArgsConstructor
public class GrabaFechasService {

    private final ControlSistemaDiaRepository control;   // MANTSISDIA IN LIB-CONTROL, función 37
    private final BaseSemanalRepository baseSemanal;     // B00-GLOB-NIV-*, S151B50TOTXCVE
    private final ControlProcesosClient b05;

    /** 01-0140: solo la función 0 persiste. Todo en una transacción para no purgar si falla el grabado. */
    @Transactional
    public void graba(ControlSistemaDia ctl, FechasProyectadas f, int nivelNuevo, LocalDate limiteBorrado) {
        ctl.setFechaProceso(f.manana());
        ctl.setNumeroArchivo(nivelNuevo - 1);
        ctl.nivel(nivelNuevo).setFecha(f.nueva());
        limpiaNiveles(ctl, nivelNuevo - 1);
        ctl.setEstatusRegistro(1);                     // STAREG = 01
        control.save(ctl);                             // si falla, la transacción revierte y no hay purga
        baseSemanal.limpiaNivelGlobal(ctl.nivelMovimiento());
        baseSemanal.borraTotalesPorClaveHasta(limiteBorrado);   // B50-MOV-FEC NOT > límite
        b05.marcaTerminado(ctl.sistema(), ctl.fechaProceso151());
    }

    /** 01-0144-LIMPIA-NIVELES: el nivel indicado y los dos anteriores, con vuelta de 1 a 10. */
    static void limpiaNiveles(ControlSistemaDia ctl, int nivel) {
        int n = nivel;
        for (int i = 0; i < 3; i++) {
            ctl.nivel(n).limpia();                     // STAARCLOG, NIVARCMOV, NIVBDMOV = 0
            n = (n == 1) ? 10 : n - 1;
        }
    }
}

