proyfecha:
  archivos:
    factor-cambio-mes: 1.1
    sistemas-con-factor: [500, 264, 404, 403, 711]
    equipos-pruebas: ["ACYPGAMA.", "VDMBETA.", "MONALFA.", "ACYPBETA."]
    registros-pruebas-cbii-ctdr: 10000
    s500: { cbii-cierre-mes: 1070000, cbii: 1010000, ctdr: 4000000, factor-descriptores: 2 }
    s264: { cbii: 10000, ctdr: 10000 }
    s335-quincena: { dia-desde: 15, dia-hasta: 20, movimientos: 180000, descriptores: 90000 }

// ---------------------------------------------------------------------------
@Component
@RequiredArgsConstructor
public class DimensionamientoArchivos {

    private final ArchivosProperties p;

    Volumenes calcula(int sistema, long base, boolean cambiaMesOInhabil, boolean mismoMes,
                      String equipo, int diaArchivo) {
        long mov = base, des = base, cbii = 0, ctdr = 0;
        if (cambiaMesOInhabil && p.sistemasConFactor().contains(sistema)) {
            mov = des = BigDecimal.valueOf(base).multiply(p.factorCambioMes())
                    .setScale(0, RoundingMode.DOWN).longValueExact();   // COMPUTE sin ROUNDED trunca
        }
        if (p.equiposPruebas().contains(equipo)) {
            if (sistema == 500 || sistema == 264) cbii = ctdr = p.registrosPruebasCbiiCtdr();
        } else if (sistema == 500) {
            cbii = mismoMes ? p.s500().cbiiCierreMes() : p.s500().cbii();
            ctdr = p.s500().ctdr();
        } else if (sistema == 264) {
            cbii = p.s264().cbii(); ctdr = p.s264().ctdr();
        } else if (sistema == 335 && diaArchivo > 14 && diaArchivo < 21) {
            mov = p.s335Quincena().movimientos(); des = p.s335Quincena().descriptores();
        }
        if (sistema == 500) des = des * p.s500().factorDescriptores();
        return new Volumenes(mov, des, cbii, ctdr);
    }
}
